import numpy as np
from scipy.optimize import least_squares
def model_cols(w, mode):
    s=np.sin(w*t); c=np.cos(w*t)
    if mode==0:
        return [np.ones_like(t),P,P**2,t,t*P,s,c,P*s,P*c]
    if mode==1:
        return [np.ones_like(t),P,P**2,t,t*P,s/P,c/P,s,c]
def sc(w,mode):
    A=np.vstack(model_cols(w,mode)).T
    cc,_,_,_=np.linalg.lstsq(A,dP_dt,rcond=None)
    return np.mean((dP_dt-A@cc)**2)/np.var(dP_dt), cc
for mode in [0,1]:
    best=min((sc(w,mode)[0],w) for w in np.linspace(0.05,3,600))
